PROCEDURE MIGRA_OM_USUARIO_REL_PARAM(P_CODOM_ATUAL IN NUMBER, P_CODOM_NOVO IN NUMBER)IS -- ######################################################################## -- -- TRATANDO OS CAMPOS DE CODOM DA TABELA SIPPES.USUARIO_RELATORIO_PARAMETRO -- -- ######################################################################## -- BEGIN CABECALHO('-- ATUALIZANDO OS CAMPOS DE CODOM DA TABELA SIPPES.USUARIO_RELATORIO_PARAMETRO'); --------------------------------------- -- ATUALIZANDO O CAMPO ORGAO_CODIGO -- --------------------------------------- UPDATE SIPPES.USUARIO_RELATORIO_PARAMETRO T SET T.ORGAO_CODIGO = P_CODOM_NOVO WHERE T.ORGAO_CODIGO = P_CODOM_ATUAL;
