PROCEDURE MIGRA_OM_PRFL_USUARIO(P_CODOM_ATUAL IN NUMBER, P_CODOM_NOVO IN NUMBER)IS -- ################################################################# -- -- TRATANDO OS CAMPOS DE CODOM DA TABELA SIPPES.ORGAO_PERFIL_USUARIO -- -- ################################################################# -- BEGIN CABECALHO('-- ATUALIZANDO OS CAMPOS DE CODOM DA TABELA SIPPES.ORGAO_PERFIL_USUARIO'); --------------------------------------- -- ATUALIZANDO O CAMPO ORGAO_CODIGO -- --------------------------------------- UPDATE SIPPES.ORGAO_PERFIL_USUARIO T SET T.ORGAO_CODIGO = P_CODOM_NOVO WHERE T.ORGAO_CODIGO = P_CODOM_ATUAL;
IMPRIMIR_MSG(SQL%ROWCOUNT, 'ORGAO_CODIGO');
END MIGRA_OM_PRFL_USUARIO;
PROCEDURE MIGRA_OM_VERSAO_USUARIO(P_CODOM_ATUAL IN NUMBER, P_CODOM_NOVO IN NUMBER)IS -- ################################################################# -- -- TRATANDO OS CAMPOS DE CODOM DA TABELA SIPPES.VERSAO_USUARIO -- -- ################################################################# -- BEGIN CABECALHO('-- ATUALIZANDO OS CAMPOS DE CODOM DA TABELA SIPPES.VERSAO_USUARIO'); --------------------------------------- -- ATUALIZANDO O CAMPO ORGAO_CODIGO -- --------------------------------------- UPDATE SIPPES.VERSAO_USUARIO VU SET VU.ORGAO_CODIGO = P_CODOM_NOVO WHERE VU.VERSAO = ( SELECT MAX(VU2.VERSAO) FROM SIPPES.VERSAO_USUARIO VU2 WHERE VU2.USUARIO_CODIGO = VU.USUARIO_CODIGO AND VU2.ATIVO_IND = 'S' AND VU2.EXCLUIDO_IND = 'N' AND VU.DATA_EXCLUSAO IS NULL AND TRUNC(SYSDATE) BETWEEN TRUNC(VU.INICIO) AND TRUNC(NVL(VU.FIM, SYSDATE)) ) AND VU.ORGAO_CODIGO = P_CODOM_ATUAL; IMPRIMIR_MSG(SQL%ROWCOUNT, 'ORGAO_CODIGO');
END MIGRA_OM_VERSAO_USUARIO;
PROCEDURE MIGRA_OM_ATUALIZACAO_CADASTRAL(P_CODOM_ATUAL IN NUMBER, P_CODOM_NOVO IN NUMBER)IS -- ################################################################# -- -- TRATANDO OS CAMPOS DE CODOM DA TABELA SIPPES.ATUALIZACAO_CADASTRAL -- -- ################################################################# -- BEGIN CABECALHO('-- ATUALIZANDO OS CAMPOS DE CODOM DA TABELA SIPPES.ATUALIZACAO_CADASTRAL'); --------------------------------------- -- ATUALIZANDO O CAMPO ORGAO_CODIGO -- --------------------------------------- UPDATE SIPPES.ATUALIZACAO_CADASTRAL AC SET AC.ORGAO_CODIGO = P_CODOM_NOVO WHERE AC.TIPO_STATUS_ALT_CODIGO <> 3 AND AC.TIPO_STATUS_ALT_CODIGO <> 4 -- OM DE ORIGEM AND AC.ORGAO_CODIGO = P_CODOM_ATUAL;
IMPRIMIR_MSG(SQL%ROWCOUNT, 'ORGAO_CODIGO');
END MIGRA_OM_ATUALIZACAO_CADASTRAL;
PROCEDURE MIGRA_OM(P_CODOM_ATUAL IN NUMBER, P_CODOM_NOVO IN NUMBER)IS -- ################################################################# -- -- REALIZAR A ATUALIZACAO DOS CAMPOS DO CODOM NA TABELAS ENVOLVIDAS -- -- ################################################################# -- BEGIN CABECALHO('-- ATUALIZANDO CODOM DA OM DE:'||P_CODOM_ATUAL||' PARA: '||P_CODOM_NOVO); MSG_SIMPLES('INICIO DA MIGRACAO', 'S'); --------------------------------------- -- ATUALIZANDO AS TABELAS ENVOLVIDAS -- --------------------------------------- MIGRA_OM_FAV_ALT(P_CODOM_ATUAL, P_CODOM_NOVO); MIGRA_OM_REMUN(P_CODOM_ATUAL, P_CODOM_NOVO); MIGRA_OM_VER_REMUN(P_CODOM_ATUAL, P_CODOM_NOVO); MIGRA_OM_LANCAMENTO(P_CODOM_ATUAL, P_CODOM_NOVO); MIGRA_OM_LANC_AVLS(P_CODOM_ATUAL, P_CODOM_NOVO); MIGRA_OM_LANC_AVLS_ALT(P_CODOM_ATUAL, P_CODOM_NOVO); MIGRA_OM_OCUPA_PNR(P_CODOM_ATUAL, P_CODOM_NOVO); MIGRA_OM_OCUPA_PNR_ALT(P_CODOM_ATUAL, P_CODOM_NOVO); MIGRA_OM_USUARIO_REL_PARAM(P_CODOM_ATUAL, P_CODOM_NOVO); MIGRA_OM_PRFL_USUARIO(P_CODOM_ATUAL, P_CODOM_NOVO); MIGRA_OM_VERSAO_USUARIO(P_CODOM_ATUAL, P_CODOM_NOVO); MIGRA_OM_ATUALIZACAO_CADASTRAL(P_CODOM_ATUAL, P_CODOM_NOVO); MSG_SIMPLES('TERMINO DA MIGRACAO', 'S');
END MIGRA_OM;
BEGIN MIGRA_OM(XXXXXX, XXXXXXX);--ATUAL, NOVO END;

            DECLARE 

    ----------------------------------------------------------------------------
    --Consulta que irá retornar os identificadores/prec_cps do(s) favorecido(s) / 
    --Instituidor(es) de pensão que deverão ser excluídos
    ----------------------------------------------------------------------------    
    CURSOR C_FAVORECIDO IS 
    SELECT R.FAV_PESSOA_IDENT_COD AS PESSOA_IDENTIFICADOR_COD,
           R.PREC_CP,
           S.CATEGORIA_FAV_CODIGO AS CATEGORIA 
    FROM SIPPES.REMUNERACAO R 
         INNER JOIN SIPPES.SUBCATEGORIA_FAVORECIDO S ON S.CODIGO = R.SUBCATEGORIA_FAV_CODIGO          
    WHERE R.PREC_CP IN ('XXXXXXXXXX');

    ----------------------------------------------------------------------------
    --Declaração de tipos
    ----------------------------------------------------------------------------    
    TYPE T_FAVORECIDO IS TABLE OF C_FAVORECIDO%ROWTYPE
    INDEX BY PLS_INTEGER;

    ----------------------------------------------------------------------------
    --Declaração de variáveis 
    ----------------------------------------------------------------------------    
    V_FAVORECIDO T_FAVORECIDO;

    V_MENSAGEM VARCHAR2(2000);    

BEGIN

    OPEN C_FAVORECIDO;

    FETCH C_FAVORECIDO BULK COLLECT INTO V_FAVORECIDO LIMIT 1000;

    CLOSE C_FAVORECIDO;

    FOR V_INDEX IN 1..V_FAVORECIDO.COUNT LOOP

        dbms_output.put_line('----------------------------- ');
        dbms_output.put_line('Favorecido nº: ' || TO_CHAR(V_INDEX)|| '(IDENT=' || V_FAVORECIDO(V_INDEX).PESSOA_IDENTIFICADOR_COD || '; PREC_CP=' || V_FAVORECIDO(V_INDEX).PREC_CP);

        BEGIN
                SIPPES.PRC_EXCLUI_FAVORECIDO(V_FAVORECIDO(V_INDEX).PESSOA_IDENTIFICADOR_COD, 
                                             V_FAVORECIDO(V_INDEX).PREC_CP,
                                             V_FAVORECIDO(V_INDEX).CATEGORIA); 
        EXCEPTION
            WHEN OTHERS THEN 
              dbms_output.put_line('Erro ao excluir favorecido: ' || SQLERRM);
        END;

    END LOOP;

    dbms_output.put_line('Operação Finalizada ');

EXCEPTION
    WHEN OTHERS THEN 
        dbms_output.put_line('Erro: ' || SQLERRM);
END PRC_EXCLUSAO_INST_TEMP;
/

            DECLARE	
vcont INT := 0;	
p_idt_atual VARCHAR2(50) := 'xxxxxxxxxxxx';	
p_idt_nova VARCHAR2(50) := 'xxxxxxxxxxxxx';	
BEGIN	

SELECT COUNT(*) INTO vcont FROM SIPPES.AGENDAMENTO_RECALCULO WHERE CUR_FAV_REM_FAV_PES_ID_COD = p_idt_atual;	
IF vcont > 0 THEN	
	DBMS_OUTPUT.PUT_LINE ('UPDATE SIPPES.AGENDAMENTO_RECALCULO SET CUR_FAV_REM_FAV_PES_ID_COD = '||CHR(39)||p_idt_nova||CHR(39)||' WHERE CUR_FAV_REM_FAV_PES_ID_COD = '||CHR(39)||p_idt_atual||CHR(39)||';');
	vcont := 0;
END IF;	
SELECT COUNT(*) INTO vcont FROM SIPPES.AJUSTE_CONTAS WHERE ALT_CAT_REM_FAV_PES_IDENT_COD = p_idt_atual;	
IF vcont > 0 THEN	
	DBMS_OUTPUT.PUT_LINE ('UPDATE SIPPES.AJUSTE_CONTAS SET ALT_CAT_REM_FAV_PES_IDENT_COD = '||CHR(39)||p_idt_nova||CHR(39)||' WHERE ALT_CAT_REM_FAV_PES_IDENT_COD = '||CHR(39)||p_idt_atual||CHR(39)||';');
	vcont := 0;
END IF;	
SELECT COUNT(*) INTO vcont FROM SIPPES.AJUSTE_CONTAS WHERE IMPL_DESI_REM_FAV_PES_ID_COD = p_idt_atual;	
IF vcont > 0 THEN	
	DBMS_OUTPUT.PUT_LINE ('UPDATE SIPPES.AJUSTE_CONTAS SET IMPL_DESI_REM_FAV_PES_ID_COD = '||CHR(39)||p_idt_nova||CHR(39)||' WHERE IMPL_DESI_REM_FAV_PES_ID_COD = '||CHR(39)||p_idt_atual||CHR(39)||';');
	vcont := 0;
END IF;	
