-- REMUNERAÇÃO SELECT fav_pessoa_ident_cod, prec_cp,orgao_codigo, em_transito_ind, orgao_destino_codigo, data_desligamento_om_origem, data_apresentacao_om_destino, '--Alterando EM_TRANSITO_IND de '|| EM_TRANSITO_IND ||' para '||'N'||CHR(13)|| 'UPDATE SIPPES.REMUNERACAO'||CHR(13)|| 'SET EM_TRANSITO_IND = '||'N'||','||CHR(13)|| 'WHERE FAV_PESSOA_IDENT_COD = '||fav_pessoa_ident_cod||CHR(13) from sippes.remuneracao VR1 where fav_pessoa_ident_cod IN ('0331901249');
-- VERSAO_REMUNERACAO SELECT VR1.REM_FAV_PESSOA_IDENT_COD, VR1.REM_PREC_CP,CHR(13)||CHR(13)|| '--Alterando a tabela: SIPPES.VERSAO_REMUNERACAO'||CHR(13)|| '--Alterando o campo EM_TRANSITO_IND de '||CHR(39)||VR1.EM_TRANSITO_IND ||CHR(39)|| ' para '||CHR(39)||'N'||CHR(39)||CHR(13)|| '--Alterando o campo MOTIVO de '||CHR(39)||VR1.MOTIVO||CHR(39)|| ' para '||CHR(39)||'Redmine CDS #47940'||CHR(39)||CHR(13)|| 'UPDATE SIPPES.VERSAO_REMUNERACAO'||CHR(13)|| 'SET EM_TRANSITO_IND = '||CHR(39)||'N'||CHR(39)||','||CHR(13)|| 'MOTIVO = '||CHR(39)||'Redmine CDS #47940'||CHR(39)||CHR(13)|| 'WHERE REM_FAV_PESSOA_IDENT_COD = '||CHR(39)||VR1.REM_FAV_PESSOA_IDENT_COD||CHR(39)||CHR(13)|| 'AND VERSAO = '||VR1.VERSAO||';'||CHR(13) from SIPPES.VERSAO_REMUNERACAO VR1 where REM_FAV_PESSOA_IDENT_COD IN ('0331901249') and VERSAO = '4';

            DECLARE  
  V_NUM_JOB             					NUMBER;   
  V_COMANDO_JOB         					VARCHAR2(1000);  
--  V_INICIO_EXECUCAO_JOB 					DATE                                    := SYSDATE+(10/86400);  -- Iniciar a execução do JOB para 10 segundos após rodar este script.
  V_INICIO_EXECUCAO_JOB 					DATE                                    := TO_DATE('02/08/2024 21:00:00','DD/MM/YYYY HH24:MI:SS'); --> Informar a data em que deverá iniciar o processamento da folha
  V_FOLHA_CODIGO        					SIPPES.FOLHA_PAGAMENTO.CODIGO%TYPE; 		--> código de identificação da folha de pagamento
  V_MES										SIPPES.FOLHA_PAGAMENTO.MES_REFERENCIA%TYPE;	--> mês da folha de pagamento
  V_ANO 									SIPPES.FOLHA_PAGAMENTO.ANO_REFERENCIA%TYPE;	--> ano da folha de pagamento

  --Nota: no caso da variável V_INICIO_EXECUCAO_JOB , informar um dos seguintes valores, conforme a necessidade:

          --> Agendar para daqui a 10 segundos: SYSDATE+(10/86400)
          --> Agendar para um data específica: TO_DATE('Dia/Mes/Ano Hora:Minuto:Segundo','DD/MM/YYYY HH24:MI:SS'). Exemplo: TO_DATE('14/12/2015 20:00:00','DD/MM/YYYY HH24:MI:SS')     

    PROCEDURE GET_CODIGO_PGTO(P_MES NUMBER, P_ANO NUMBER, P_CODIGO OUT NUMBER)
    IS    
    BEGIN
        SELECT CODIGO
        INTO P_CODIGO 
        FROM SIPPES.FOLHA_PAGAMENTO
        WHERE MES_REFERENCIA = P_MES
          AND ANO_REFERENCIA = P_ANO; 
    END GET_CODIGO_PGTO;		  
BEGIN  

	V_MES := 7;
	V_ANO := 2024;

	GET_CODIGO_PGTO(V_MES, V_ANO, V_FOLHA_CODIGO);

    V_COMANDO_JOB := 'BEGIN '||
                     'SIPPES.PRC_GERA_FICHA_FINANCEIRA('||TRIM(TO_CHAR(V_FOLHA_CODIGO))||');'||
                     'END;';

    SIPPES.PRC_EFETUA_AGENDAMENTO(P_COMANDO_JOB => V_COMANDO_JOB,  |
                                  P_INICIO_EXECUCAO_JOB => V_INICIO_EXECUCAO_JOB, 
                                  P_NUM_JOB => V_NUM_JOB);   

    dbms_output.put_line('Agendamento '||V_NUM_JOB||' realizado com sucesso!');  

EXCEPTION
    WHEN OTHERS THEN 
        dbms_output.put_line('Erro ao agendar: ' || SQLERRM);        
END; 
/


select * from dba_jobs WHERE JOB = 35679;

--SELECT * FROM DBA_JOBS;
/* ========================================================================== I D E N T I F I C A C A O ========================================================================== SIPPES - Sistema de Pagamento de Pessoal (Exercito) ------------------------------------------------------------------------- NOME DO OBJETO :BLOCO ANONIMO OBJETIVO : Realizar o(s) agendamento(s) do processo da geraContraCheque. PARAMETROS : V_FOLHA_PGTO -- Armazena o codigo da folha de pagamento desejada V_UNIVERSO_A_SER_PAGO1 -- Deverá ser informado o UNIVERSO A SER PAGO para a 1a CORRIDA no processamento completo V_UNIVERSO_A_SER_PAGO2 -- Deverá ser informado o UNIVERSO A SER PAGO para a 2a CORRIDA no processamento completo V_UNIVERSO_A_SER_PAGO3 -- Deverá ser informado o UNIVERSO A SER PAGO para a 3a CORRIDA no processamento completo V_MES -- Deverá ser informado o MES de pagamento a ser gerado a geração do Contracheques V_ANO -- Deverá ser informado o ANO de pagamento a ser gerado a geração do Contracheques V_INICIO_EXECUCAO_JOB -- Deverá ser informado o DATA/HORA que deve ocorrer o processamento V_UNIVERSO_A_SER_PAGO -- Deverá ser informado o UNIVERSO A SER PAGO para uma CORRIDA EXTRA (SFC) no processamento completo
========================================================================== C O N T R O L E D E A L T E R A C O E S: ========================================================================== NUMERO DA VERSAO : 001 DATA DA VERSAO : 28/05/2021 RESPONSAVEL : Cap Audirio DESC. DA ALTERACAO : Criacão */
DECLARE
-- VARIAVEIS COMUMN A TODO O PROCESSAMENTO DA FOLHA V_FOLHA_PGTO NUMBER; V_MES NUMBER; V_ANO NUMBER;
-- VARIAVEIS PARA O PROCESSAMENTO COMPLETO DA FOLHA V_UNIVERSO_A_SER_PAGO1 NUMBER; V_UNIVERSO_A_SER_PAGO2 NUMBER; V_UNIVERSO_A_SER_PAGO3 NUMBER; V_NUMERO_PROCESSAMENTO1 NUMBER; V_NUMERO_PROCESSAMENTO2 NUMBER; V_NUMERO_PROCESSAMENTO3 NUMBER;
-- VARIAVEIS PARA O PROCESSAMENTO INDIVIDUAL DA FOLHA V_INICIO_EXECUCAO_JOB DATE; V_UNIVERSO_A_SER_PAGO NUMBER; V_NUMERO_PROCESSAMENTO NUMBER; /* ========================================================================== I D E N T I F I C A C A O ========================================================================== NOME DA OBJETO : GET_CODIGO_PGTO OBJETIVO : Retorna o CODIGO da folha de pagamento do mes/ano informado PARAMETROS : P_MES - Corresponde ao mes de pagamento. P_ANO - Corresponde ao ano de pagamento. P_CODIGO - Corresponde ao retorno do codigo da folha de pagamento. ------------------------------------------------------------------------- */ PROCEDURE GET_CODIGO_PGTO(P_MES NUMBER, P_ANO NUMBER, P_CODIGO OUT NUMBER) IS BEGIN SELECT CODIGO INTO P_CODIGO FROM SIPPES.FOLHA_PAGAMENTO WHERE MES_REFERENCIA = P_MES AND ANO_REFERENCIA = P_ANO; END GET_CODIGO_PGTO;
/* ========================================================================== I D E N T I F I C A C A O ========================================================================== NOME DA OBJETO : AGENDAR_JOB_GERACC OBJETIVO : Realiza o agendamento do JOB da geraContraCheque para o processamento informado. PARAMETROS : P_FOLHA_PGTO - Corresponde ao codigo da folha de pagamento. P_INICIO_EXECUCAO_JOB - Corresponde a data/hora que deve iniciar a execução do JOB. P_UNIVERSO_A_SER_PAGO - Corresponde ao universo que deverá ser processado. ------------------------------------------------------------------------- */ PROCEDURE AGENDAR_JOB_GERACC(P_FOLHA_PGTO IN NUMBER, P_INICIO_EXECUCAO_JOB IN DATE DEFAULT TO_DATE('01/01/1900 00:00:00', 'DD/MM/YYYY HH24:MI:SS'), P_UNIVERSO_A_SER_PAGO IN NUMBER DEFAULT 13, P_NUMERO_PROCESSAMENTO IN NUMBER) IS V_NUM_JOB NUMBER; V_COMANDO_JOB VARCHAR2(1000); V_INICIO_EXECUCAO_JOB DATE DEFAULT TO_DATE('01/01/1900 00:00:00', 'DD/MM/YYYY HH24:MI:SS');
BEGIN
IF V_INICIO_EXECUCAO_JOB = P_INICIO_EXECUCAO_JOB THEN -- Agendar para executar migração depois de 10 segundos da realização do JOB. V_INICIO_EXECUCAO_JOB := TO_CHAR(SYSDATE + (10/86400), 'DD/MM/YYYY HH24:MI:SS'); ELSE --Agendar para executar na DATAHORA informada. V_INICIO_EXECUCAO_JOB := P_INICIO_EXECUCAO_JOB; END IF;
V_COMANDO_JOB := 'BEGIN ' || 'SIPPES.PRC_CARREGA_GERACONTRACHEQUE(' || TRIM(P_FOLHA_PGTO) ||', '||P_UNIVERSO_A_SER_PAGO||', '||P_NUMERO_PROCESSAMENTO||'); '|| ' END; ';
SIPPES.PRC_EFETUA_AGENDAMENTO(P_COMANDO_JOB => V_COMANDO_JOB, P_INICIO_EXECUCAO_JOB => V_INICIO_EXECUCAO_JOB, P_NUM_JOB => V_NUM_JOB);
-- HABILITAR O DBMS PARA REALIZAR TESTES -- DBMS_OUTPUT.PUT_LINE('P_COMANDO_JOB =>'|| V_COMANDO_JOB||', -- P_INICIO_EXECUCAO_JOB => '||CHR(39)||TO_CHAR(V_INICIO_EXECUCAO_JOB, 'DD/MM/YYYY HH24:MI:SS')||CHR(39) ||', -- P_NUM_JOB => '||V_NUM_JOB); -- DBMS_OUTPUT.PUT_LINE(V_COMANDO_JOB);
DBMS_OUTPUT.PUT_LINE('AGENDAMENTO REALIZADO COM SUCESSO!'); EXCEPTION WHEN OTHERS THEN DBMS_OUTPUT.PUT_LINE('ERRO AO AGENDAR: ' || SQLCODE||' - '||SQLERRM);
END AGENDAR_JOB_GERACC;
/* ========================================================================== I D E N T I F I C A C A O ========================================================================== NOME DA OBJETO : AGENDAMENTO_COMPLETO OBJETIVO : Executa o agendamento da geraContraCheque para a três definidas na tabela SIPPES.FOLHA_PAGAMENTO PARAMETROS : P_CODIGO - Corresponde ao codigo da folha de pagamento. P_UNIVERSO1 - Corresponde ao UNIVERSO da 1ª corrida da folha de pagamento. P_UNIVERSO2 - Corresponde ao UNIVERSO da 2ª corrida da folha de pagamento. P_UNIVERSO3 - Corresponde ao UNIVERSO da 3ª corrida da folha de pagamento. ------------------------------------------------------------------------- */ PROCEDURE AGENDAMENTO_COMPLETO(P_CODIGO IN NUMBER, P_UNIVERSO1 IN NUMBER DEFAULT 13, P_UNIVERSO2 IN NUMBER DEFAULT 13, P_UNIVERSO3 IN NUMBER DEFAULT 13, P_NUMERO_PROCESSAMENTO1 IN NUMBER DEFAULT 1, P_NUMERO_PROCESSAMENTO2 IN NUMBER DEFAULT 2, P_NUMERO_PROCESSAMENTO3 IN NUMBER DEFAULT 3) IS V_PRIMEIRA_CORRIDA DATE; -- Data do processamento OM constante da tabela SIPPES.FOLHA_PAGAMENTO V_SEGUNDA_CORRIDA DATE; -- Data do processamento CPEx constante da tabela SIPPES.FOLHA_PAGAMENTO V_TERCEIRA_CORRIDA DATE; -- Data do processamento Final constante da tabela SIPPES.FOLHA_PAGAMENTO V_FOLHA_PGTO NUMBER; -- Corresponde ao codigo da folha de pagamento retornado na procedure GET_CODIGO_PGTO.
CURSOR CUR_CORRIDAS IS SELECT FA.DATA_PROCESSAMENTO_OM - (1/24) AS PRIMEIRA_CORRIDA, FA.DATA_PROCESSAMENTO_CPEX - (1/24) AS SEGUNDA_CORRIDA, FA.DATA_PROCESSAMENTO_FINAL - (1/24) AS TERCEIRA_CORRIDA FROM SIPPES.FOLHA_PAGAMENTO FA WHERE CODIGO = P_CODIGO;
BEGIN FOR I IN CUR_CORRIDAS LOOP -- 1a CORRIDA AGENDAR_JOB_GERACC(P_CODIGO, I.PRIMEIRA_CORRIDA, P_UNIVERSO1, P_NUMERO_PROCESSAMENTO1);
-- 2a CORRIDA AGENDAR_JOB_GERACC(P_CODIGO, I.SEGUNDA_CORRIDA, P_UNIVERSO2, P_NUMERO_PROCESSAMENTO2);
-- 3a CORRIDA AGENDAR_JOB_GERACC(P_CODIGO, I.TERCEIRA_CORRIDA, P_UNIVERSO3, P_NUMERO_PROCESSAMENTO3); END LOOP; END AGENDAMENTO_COMPLETO;
-- INICIO DA EXECUCAO DO AGENDAMENTO DA GERA CONTRACHEQUE BEGIN /* ========================================================================== -- UNIVERSOS DEFINIDOS NA PROCEDURE SIPPES.PRC_CARREGA_GERACONTRACHEQUE ==========================================================================
UNIVERSO_A_SER_PAGO = 10 -- (1) Militar Carreira, Temporário e Efetivo Variável
UNIVERSO_A_SER_PAGO = 11 -- (1) Militar Carreira, Temporário e Efetivo Variável -- (2) Reserva, Reforma Incapacidade, Reforma Invalidez, Anistiado, DSA, Reforma Ordem Judicial, Reforma Amparo Estado e Reforma por Idade Limite
UNIVERSO_A_SER_PAGO = 12 -- (1) Militar Carreira, Temporário e Efetivo Variável -- (2) Reserva, Reforma Incapacidade, Reforma Invalidez, Anistiado, DSA, Reforma Ordem Judicial, Reforma Amparo Estado e Reforma por Idade Limite -- (3) Pensionista
UNIVERSO_A_SER_PAGO = 13 (DEFAULT) -- (2) Temporario -- (3) Efetivo Variável
UNIVERSO_A_SER_PAGO = 15 -- (2) Temporario -- (3) Efetivo Variável -- (X) Carreira a partir de 2013 ========================================================================== */ /* ========================================================================== -- REALIZANDO O AGENDAMENTO COMPLETO DA FOLHA ========================================================================== */ -- ********************************************************************* -- CARREGANDO VARIAVEIS COMUNS A QUALQUER AGENDAMENTO -- ********************************************************************* -- DEFINIR MES E ANO A SEREM PROCESSADOS V_MES := 8; -- DEFINIR O MES QUE DESEJA AGENDAR V_ANO := 2024; -- DEFINIR O ANO QUE DESEJA AGENDAR
-- RECUPERANDO O CODIGO DA FOLHA DE PAGAMENTO DO MES/ANO PRETENDIDO GET_CODIGO_PGTO(V_MES, V_ANO, V_FOLHA_PGTO);
-- ********************************************************************* -- CARREGANDO VARIAVEIS PARA REALIZAR AGENDAMENTO COMPLETO -- ********************************************************************* /* -- DEFINIR UNIVERSOS A SEREM PROCESSADOS -- DESCOMENTAR AS TRÊS LINHAS ABAIXO PARA DEFINIR OS UNIVERSOS DE CADA CORRIDA V_UNIVERSO_A_SER_PAGO1 := 15; -- DEFINIR O UNIVERSO A SER PROCESSANDO NA 1ª CORRIDA V_UNIVERSO_A_SER_PAGO2 := 15; -- DEFINIR O UNIVERSO A SER PROCESSANDO NA 2ª CORRIDA V_UNIVERSO_A_SER_PAGO3 := 15; -- DEFINIR O UNIVERSO A SER PROCESSANDO NA 3ª CORRIDA
-- DEFINIR UNIVERSOS A SEREM PROCESSADOS -- DESCOMENTAR AS TRÊS LINHAS ABAIXO PARA DEFINIR OS NUMEROS DE PROCESSAMENTO DE CADA CORRIDA V_NUMERO_PROCESSAMENTO1 := 1; -- DEFINIR NR PROCESSANDO NA 1ª CORRIDA V_NUMERO_PROCESSAMENTO2 := 2; -- DEFINIR NR PROCESSANDO NA 2ª CORRIDA V_NUMERO_PROCESSAMENTO3 := 3; -- DEFINIR NR PROCESSANDO NA 3ª CORRIDA */ -- ********************************************************************* -- REALIZANDO O AGENDAMENTO COMPLETO DAS CORRIDAS CONFORME TABELA SIPPES.FOLHA_PAGAMENTO -- ********************************************************************* -- AGENDAMENTO_COMPLETO(V_FOLHA_PGTO, V_UNIVERSO_A_SER_PAGO1, V_UNIVERSO_A_SER_PAGO2, V_UNIVERSO_A_SER_PAGO3);
/* ========================================================================== -- REALIZANDO O AGENDAMENTO PARA CORRIDA INDIVIDUAL (SFC) ========================================================================== */ -- ********************************************************************* -- CARREGANDO VARIAVEIS PARA REALIZAR AGENDAMENTO PARA CORRIDA INDIVIDUAL (SFC) -- *********************************************************************
V_NUMERO_PROCESSAMENTO := 2; -- ALTERAR CONFORME O CASO (1, 2, 3) V_UNIVERSO_A_SER_PAGO := 15; V_INICIO_EXECUCAO_JOB := TO_DATE('17/08/2024 17:00:00', 'DD/MM/YYYY HH24:MI:SS');
AGENDAR_JOB_GERACC(V_FOLHA_PGTO, V_INICIO_EXECUCAO_JOB, V_UNIVERSO_A_SER_PAGO, V_NUMERO_PROCESSAMENTO);
END; /



Altera  
DECLARE

PROCEDURE ATUALIZA_SUBCATEGORIA(P_IDT VARCHAR2, P_SUBCAT NUMBER) IS
V_MSG                   VARCHAR2(255);
V_ERRO					NUMBER := 0;
E_FAVORECIDO_ALT		EXCEPTION;
E_REMUNERACAO			EXCEPTION;
E_VERSAO_REMUNERACAO	EXCEPTION;
/*
----------------------------------------------------
-- VALORES POSSIVEIS PARA SUBCATEGORIA (P_SUBCAT) --
----------------------------------------------------
1	CARREIRA
2	TEMPORARIO
3	EFETIVO VARIAVEL
4	RESERVA
5	REFORMA INCAPACIDADE
6	REFORMA INVALIDEZ
7	ANISTIADO
9	DSA
10	PENSIONISTA
11	REFORMA ORDEM JUDICIAL
12	REFORMA AMPARO ESTADO
13	REFORMA POR IDADE LIMITE
14	INSTITUIDOR DA PENSAO
*/ 
BEGIN


    BEGIN
        UPDATE SIPPES.FAVORECIDO_ALT F
        SET F.SUBCATEGORIA_FAV_CODIGO = P_SUBCAT
        WHERE F.PESSOA_IDENTIFICADOR_COD = P_IDT
        AND   F.VERSAO_ALTERACAO = (SELECT MAX(F2.VERSAO_ALTERACAO) 
                          FROM SIPPES.FAVORECIDO_ALT F2
                          WHERE F2.PESSOA_IDENTIFICADOR_COD = P_IDT)
                          ;

        IF SQL%ROWCOUNT = 0 THEN
			V_ERRO := V_ERRO + 1;
            RAISE E_FAVORECIDO_ALT;
        END IF;

	EXCEPTION
		WHEN E_FAVORECIDO_ALT THEN
			DBMS_OUTPUT.PUT_LINE('ERRO NA ATUALIZACAO DA IDT '|| P_IDT ||' EM SIPPES.FAVORECIDO_ALT');
    END;

    BEGIN
        UPDATE SIPPES.REMUNERACAO R
        SET R.SUBCATEGORIA_FAV_CODIGO = P_SUBCAT
        WHERE R.FAV_PESSOA_IDENT_COD =  P_IDT;

        IF SQL%ROWCOUNT = 0 THEN
			V_ERRO := V_ERRO + 1;
            RAISE E_REMUNERACAO;
        END IF;

	EXCEPTION
		WHEN E_REMUNERACAO THEN
			DBMS_OUTPUT.PUT_LINE('ERRO NA ATUALIZACAO DA IDT '|| P_IDT || ' EM SIPPES.REMUNERACAO');
    END;

    BEGIN
        UPDATE SIPPES.VERSAO_REMUNERACAO R
        SET R.SUBCATEGORIA_FAV_CODIGO = P_SUBCAT
        WHERE R.REM_FAV_PESSOA_IDENT_COD = P_IDT
        AND   R.VERSAO = (SELECT MAX(R2.VERSAO) 
                          FROM SIPPES.VERSAO_REMUNERACAO R2
                          WHERE R2.REM_FAV_PESSOA_IDENT_COD = P_IDT)
                          ;

        IF SQL%ROWCOUNT = 0 THEN
			V_ERRO := V_ERRO + 1;
            RAISE E_VERSAO_REMUNERACAO;
        END IF;

	EXCEPTION
		WHEN E_VERSAO_REMUNERACAO THEN
			DBMS_OUTPUT.PUT_LINE('ERRO NA ATUALIZACAO DA IDT '|| P_IDT || ' EM SIPPES.VERSAO_REMUNERACAO');
    END;

    IF V_ERRO = 0 THEN
       V_MSG := 'ATUALIZACAO DE SUBCATEGORIA  PARA A IDT '|| P_IDT ||' REALIZADA COM SUCESSO';
    END IF;

    DBMS_OUTPUT.PUT_LINE(V_MSG);
END;    
BEGIN   

        ATUALIZA_SUBCATEGORIA('0310245071', 2);

END;
/

/*
    SELECT  'FAVORECIDO_ALT', F.SUBCATEGORIA_FAV_CODIGO
    FROM FAVORECIDO_ALT F 
    WHERE F.PESSOA_IDENTIFICADOR_COD IN (
    '0402555478'
    )
    AND F.VERSAO_ALTERACAO = (SELECT MAX(F2.VERSAO_ALTERACAO) 
                              FROM SIPPES.FAVORECIDO_ALT F2
                              WHERE F2.PESSOA_IDENTIFICADOR_COD = F.PESSOA_IDENTIFICADOR_COD)

    --ORDER BY F.VERSAO_ALTERACAO DESC 
    union

    SELECT  'VERSAO_REMUNERACAO', R.SUBCATEGORIA_FAV_CODIGO
    FROM SIPPES.VERSAO_REMUNERACAO R
    WHERE R.REM_FAV_PESSOA_IDENT_COD IN (
    '0402555478'
    )
    AND R.VERSAO = (SELECT MAX(R2.VERSAO) 
                              FROM SIPPES.VERSAO_REMUNERACAO R2
                              WHERE R2.REM_FAV_PESSOA_IDENT_COD = R.REM_FAV_PESSOA_IDENT_COD)
    --ORDER BY R2.VERSAO DESC   
    union

    SELECT 'REMUNERACAO', R3.SUBCATEGORIA_FAV_CODIGO
    FROM SIPPES.REMUNERACAO R3
    WHERE R3.FAV_PESSOA_IDENT_COD IN (
    '0402555478'
    );

/* SCRIPT COM A FINALIDADE DE EFETUAR A MIGRACAO DE CODOM ENTRE UNIDADES */ DECLARE -- V_CODOM_ATUAL SIPPES.FAVORECIDO_ALT.ORGAO_CODIGO%TYPE := 62133; -- V_CODOM_NOVO SIPPES.FAVORECIDO_ALT.ORGAO_CODIGO%TYPE := 62315;
-- PROCEDURE PARA GERAR O CABECALHO PROCEDURE CABECALHO(P_TEXTO IN VARCHAR2) IS BEGIN
DBMS_OUTPUT.PUT_LINE('--############################################################--'); DBMS_OUTPUT.PUT_LINE(P_TEXTO); DBMS_OUTPUT.PUT_LINE('--############################################################--');
END CABECALHO;
-- PROCEDIMENTO PARA IMPRIMIR A MENSAGEM DE ATUALIZACAO PROCEDURE IMPRIMIR_MSG(P_LINHA IN NUMBER, P_CAMPO IN VARCHAR2, P_FIM VARCHAR2 DEFAULT 'N') IS BEGIN
IF P_LINHA = 0 THEN DBMS_OUTPUT.PUT_LINE('CAMPO '||P_CAMPO||': NAO HA REGISTRO A SER ALTERADO'); ELSE DBMS_OUTPUT.PUT_LINE('CAMPO '||P_CAMPO||': FOI(RAM) ATUALIZADO(S) ' || SQL%ROWCOUNT || ' REGISTRO(S)'); END IF;
IF P_FIM = 'S' THEN DBMS_OUTPUT.PUT_LINE('--'); END IF;
END IMPRIMIR_MSG;
-- PROCEDIMENTO PARA IMPRIMIR A MENSAGEM DE ATUALIZACAO PROCEDURE MSG_SIMPLES(P_TEXTO IN VARCHAR2, P_LINHA IN VARCHAR2 DEFAULT 'S') IS V_LINHA VARCHAR2(1000) := NULL; V_EXTREMO VARCHAR2(2) := '--'; BEGIN IF P_LINHA = 'N' THEN DBMS_OUTPUT.PUT_LINE(P_TEXTO); ELSE FOR I IN 1..LENGTH(P_TEXTO)+1 LOOP V_LINHA := V_LINHA || '*'; END LOOP; DBMS_OUTPUT.PUT_LINE(V_EXTREMO||V_LINHA||V_EXTREMO); DBMS_OUTPUT.PUT_LINE(V_EXTREMO||P_TEXTO||V_EXTREMO); DBMS_OUTPUT.PUT_LINE(V_EXTREMO||V_LINHA||V_EXTREMO); END IF; END MSG_SIMPLES;
PROCEDURE MIGRA_OM_FAV_ALT(P_CODOM_ATUAL IN NUMBER, P_CODOM_NOVO IN NUMBER, P_GESTORA IN NUMBER DEFAULT NULL)IS -- TRATANDO OS CAMPOS DE CODOM DA TABELA SIPPES.FAVORECIDO_ALT BEGIN CABECALHO('-- ATUALIZANDO OS CAMPOS DE CODOM DA TABELA SIPPES.FAVORECIDO_ALT'); -- ################################# -- -- TRATANDO OS REGISTROS HOMOLOGADOS -- -- ################################# -- MSG_SIMPLES('TRATANDO OS REGISTROS HOMOLOGADOS'); -------------------------------------- -- ATUALIZANDO O CAMPO ORGAO_CODIGO -- -------------------------------------- UPDATE SIPPES.FAVORECIDO_ALT F SET F.ORGAO_CODIGO = P_CODOM_NOVO WHERE F.ORGAO_CODIGO = P_CODOM_ATUAL AND EM_TRANSITO_IND = 'N' AND F.VERSAO_ALTERACAO = (SELECT MAX(F2.VERSAO_ALTERACAO) FROM SIPPES.FAVORECIDO_ALT F2 WHERE F2.PESSOA_IDENTIFICADOR_COD = F.PESSOA_IDENTIFICADOR_COD AND F2.PREC_CP = F.PREC_CP AND F2.TIPO_STATUS_ALT_CODIGO = 3 AND F2.TIPO_SITUACAO_LANC_CAD_COD = 9); IMPRIMIR_MSG(SQL%ROWCOUNT, 'ORGAO_CODIGO');
----------------------------------------------- -- ATUALIZANDO O CAMPO ORGAO_ANTERIOR_CODIGO -- ----------------------------------------------- UPDATE SIPPES.FAVORECIDO_ALT F SET F.ORGAO_ANTERIOR_CODIGO = P_CODOM_NOVO WHERE F.ORGAO_ANTERIOR_CODIGO = P_CODOM_ATUAL AND EM_TRANSITO_IND = 'N' AND F.VERSAO_ALTERACAO = (SELECT MAX(F2.VERSAO_ALTERACAO) FROM SIPPES.FAVORECIDO_ALT F2 WHERE F2.PESSOA_IDENTIFICADOR_COD = F.PESSOA_IDENTIFICADOR_COD AND F2.PREC_CP = F.PREC_CP AND F2.TIPO_STATUS_ALT_CODIGO = 3 AND F2.TIPO_SITUACAO_LANC_CAD_COD = 9); IMPRIMIR_MSG(SQL%ROWCOUNT, 'ORGAO_ANTERIOR_CODIGO');
---------------------------------------------- -- ATUALIZANDO O CAMPO ORGAO_DESTINO_CODIGO -- ---------------------------------------------- UPDATE SIPPES.FAVORECIDO_ALT F SET F.ORGAO_DESTINO_CODIGO = P_CODOM_NOVO WHERE F.ORGAO_DESTINO_CODIGO = P_CODOM_ATUAL AND EM_TRANSITO_IND = 'N' AND F.VERSAO_ALTERACAO = (SELECT MAX(F2.VERSAO_ALTERACAO) FROM SIPPES.FAVORECIDO_ALT F2 WHERE F2.PESSOA_IDENTIFICADOR_COD = F.PESSOA_IDENTIFICADOR_COD AND F2.PREC_CP = F.PREC_CP AND F2.TIPO_STATUS_ALT_CODIGO = 3 AND F2.TIPO_SITUACAO_LANC_CAD_COD = 9); IMPRIMIR_MSG(SQL%ROWCOUNT, 'ORGAO_DESTINO_CODIGO', 'S');
-- ################################# -- -- TRATANDO OS REGISTROS EM TRANSITO -- -- ################################# -- MSG_SIMPLES('TRATANDO OS REGISTROS EM TRANSITO'); -------------------------------------- -- ATUALIZANDO O CAMPO ORGAO_CODIGO -- -------------------------------------- UPDATE SIPPES.FAVORECIDO_ALT F SET F.ORGAO_CODIGO = P_CODOM_NOVO WHERE F.ORGAO_CODIGO = P_CODOM_ATUAL AND EM_TRANSITO_IND = 'S' AND F.VERSAO_ALTERACAO = (SELECT MAX(F2.VERSAO_ALTERACAO) FROM SIPPES.FAVORECIDO_ALT F2 WHERE F2.PESSOA_IDENTIFICADOR_COD = F.PESSOA_IDENTIFICADOR_COD AND F2.PREC_CP = F.PREC_CP AND F2.TIPO_STATUS_ALT_CODIGO = 3 AND F2.TIPO_SITUACAO_LANC_CAD_COD = 9);--00 (produção) --03 (homologação) IMPRIMIR_MSG(SQL%ROWCOUNT, 'ORGAO_CODIGO'); ----------------------------------------------- -- ATUALIZANDO O CAMPO ORGAO_ANTERIOR_CODIGO -- ----------------------------------------------- UPDATE SIPPES.FAVORECIDO_ALT F SET F.ORGAO_ANTERIOR_CODIGO = P_CODOM_NOVO WHERE F.ORGAO_ANTERIOR_CODIGO = P_CODOM_ATUAL AND EM_TRANSITO_IND = 'S' AND F.VERSAO_ALTERACAO = (SELECT MAX(F2.VERSAO_ALTERACAO) FROM SIPPES.FAVORECIDO_ALT F2 WHERE F2.PESSOA_IDENTIFICADOR_COD = F.PESSOA_IDENTIFICADOR_COD AND F2.PREC_CP = F.PREC_CP AND F2.TIPO_STATUS_ALT_CODIGO = 3 AND F2.TIPO_SITUACAO_LANC_CAD_COD = 9); IMPRIMIR_MSG(SQL%ROWCOUNT, 'ORGAO_ANTERIOR_CODIGO'); ---------------------------------------------- -- ATUALIZANDO O CAMPO ORGAO_DESTINO_CODIGO -- ---------------------------------------------- UPDATE SIPPES.FAVORECIDO_ALT F SET F.ORGAO_DESTINO_CODIGO = P_CODOM_NOVO WHERE F.ORGAO_DESTINO_CODIGO = P_CODOM_ATUAL AND EM_TRANSITO_IND = 'S' AND F.VERSAO_ALTERACAO = (SELECT MAX(F2.VERSAO_ALTERACAO) FROM SIPPES.FAVORECIDO_ALT F2 WHERE F2.PESSOA_IDENTIFICADOR_COD = F.PESSOA_IDENTIFICADOR_COD AND F2.PREC_CP = F.PREC_CP AND F2.TIPO_STATUS_ALT_CODIGO = 3 AND F2.TIPO_SITUACAO_LANC_CAD_COD = 9); IMPRIMIR_MSG(SQL%ROWCOUNT, 'ORGAO_DESTINO_CODIGO', 'S');
-- ################################################################################ -- -- TRATANDO OS REGISTROS NAO EM TRANSITO O E TIPO_STATUS_ALT_CODIGO NAO SEJA 3 OU 4 -- -- ################################################################################ -- MSG_SIMPLES('TRATANDO OS REGISTROS NAO EM TRANSITO E TIPO_STATUS_ALT_CODIGO NAO SEJA 3 OU 4'); -------------------------------------- -- ATUALIZANDO O CAMPO ORGAO_CODIGO -- -------------------------------------- UPDATE SIPPES.FAVORECIDO_ALT F SET F.ORGAO_CODIGO = P_CODOM_NOVO WHERE F.ORGAO_CODIGO = P_CODOM_ATUAL AND EM_TRANSITO_IND = 'N' AND F.VERSAO_ALTERACAO = (SELECT MAX(F2.VERSAO_ALTERACAO) FROM SIPPES.FAVORECIDO_ALT F2 WHERE F2.PESSOA_IDENTIFICADOR_COD = F.PESSOA_IDENTIFICADOR_COD AND F2.PREC_CP = F.PREC_CP) AND F.TIPO_STATUS_ALT_CODIGO NOT IN (3,4); IMPRIMIR_MSG(SQL%ROWCOUNT, 'ORGAO_CODIGO'); ----------------------------------------------- -- ATUALIZANDO O CAMPO ORGAO_ANTERIOR_CODIGO -- ----------------------------------------------- UPDATE SIPPES.FAVORECIDO_ALT F SET F.ORGAO_ANTERIOR_CODIGO = P_CODOM_NOVO WHERE F.ORGAO_ANTERIOR_CODIGO = P_CODOM_ATUAL AND EM_TRANSITO_IND = 'N' AND F.VERSAO_ALTERACAO = (SELECT MAX(F2.VERSAO_ALTERACAO) FROM SIPPES.FAVORECIDO_ALT F2 WHERE F2.PESSOA_IDENTIFICADOR_COD = F.PESSOA_IDENTIFICADOR_COD AND F2.PREC_CP = F.PREC_CP)
AND F.TIPO_STATUS_ALT_CODIGO NOT IN (3,4); IMPRIMIR_MSG(SQL%ROWCOUNT, 'ORGAO_ANTERIOR_CODIGO'); ---------------------------------------------- -- ATUALIZANDO O CAMPO ORGAO_DESTINO_CODIGO -- ---------------------------------------------- UPDATE SIPPES.FAVORECIDO_ALT F SET F.ORGAO_DESTINO_CODIGO = P_CODOM_NOVO WHERE F.ORGAO_DESTINO_CODIGO = P_CODOM_ATUAL AND EM_TRANSITO_IND = 'N' AND F.VERSAO_ALTERACAO = (SELECT MAX(F2.VERSAO_ALTERACAO) FROM SIPPES.FAVORECIDO_ALT F2 WHERE F2.PESSOA_IDENTIFICADOR_COD = F.PESSOA_IDENTIFICADOR_COD AND F2.PREC_CP = F.PREC_CP) AND F.TIPO_STATUS_ALT_CODIGO NOT IN (3,4); IMPRIMIR_MSG(SQL%ROWCOUNT, 'ORGAO_DESTINO_CODIGO', 'S');
-- ############################################################################# -- -- TRATANDO OS REGISTROS EM TRANSITO E TIPO_STATUS_ALT_CODIGO QUE NAO SEJA 3 OU 4 -- -- ############################################################################# -- MSG_SIMPLES('TRATANDO OS REGISTROS EM TRANSITO E TIPO_STATUS_ALT_CODIGO QUE NAO SEJA 3 OU 4'); -------------------------------------- -- ATUALIZANDO O CAMPO ORGAO_CODIGO -- -------------------------------------- UPDATE SIPPES.FAVORECIDO_ALT F SET F.ORGAO_CODIGO = P_CODOM_NOVO WHERE F.ORGAO_CODIGO = P_CODOM_ATUAL AND EM_TRANSITO_IND = 'S' AND F.VERSAO_ALTERACAO = (SELECT MAX(F2.VERSAO_ALTERACAO) FROM SIPPES.FAVORECIDO_ALT F2 WHERE F2.PESSOA_IDENTIFICADOR_COD = F.PESSOA_IDENTIFICADOR_COD AND F2.PREC_CP = F.PREC_CP) AND F.TIPO_STATUS_ALT_CODIGO NOT IN (3,4); IMPRIMIR_MSG(SQL%ROWCOUNT, 'ORGAO_CODIGO'); ----------------------------------------------- -- ATUALIZANDO O CAMPO ORGAO_ANTERIOR_CODIGO -- ----------------------------------------------- UPDATE SIPPES.FAVORECIDO_ALT F SET F.ORGAO_ANTERIOR_CODIGO = P_CODOM_NOVO WHERE F.ORGAO_ANTERIOR_CODIGO = P_CODOM_ATUAL AND EM_TRANSITO_IND = 'S' AND F.VERSAO_ALTERACAO = (SELECT MAX(F2.VERSAO_ALTERACAO) FROM SIPPES.FAVORECIDO_ALT F2 WHERE F2.PESSOA_IDENTIFICADOR_COD = F.PESSOA_IDENTIFICADOR_COD AND F2.PREC_CP = F.PREC_CP) AND F.TIPO_STATUS_ALT_CODIGO NOT IN (3,4); IMPRIMIR_MSG(SQL%ROWCOUNT, 'ORGAO_ANTERIOR_CODIGO'); ---------------------------------------------- -- ATUALIZANDO O CAMPO ORGAO_DESTINO_CODIGO -- ---------------------------------------------- UPDATE SIPPES.FAVORECIDO_ALT F SET F.ORGAO_DESTINO_CODIGO = P_CODOM_NOVO WHERE F.ORGAO_DESTINO_CODIGO = P_CODOM_ATUAL AND EM_TRANSITO_IND = 'S' AND F.VERSAO_ALTERACAO = (SELECT MAX(F2.VERSAO_ALTERACAO) FROM SIPPES.FAVORECIDO_ALT F2 WHERE F2.PESSOA_IDENTIFICADOR_COD = F.PESSOA_IDENTIFICADOR_COD AND F2.PREC_CP = F.PREC_CP) AND F.TIPO_STATUS_ALT_CODIGO NOT IN (3,4); IMPRIMIR_MSG(SQL%ROWCOUNT, 'ORGAO_DESTINO_CODIGO', 'S');
END MIGRA_OM_FAV_ALT;
PROCEDURE MIGRA_OM_REMUN(P_CODOM_ATUAL IN NUMBER, P_CODOM_NOVO IN NUMBER, P_GESTORA IN NUMBER DEFAULT NULL)IS -- ######################################################## -- -- TRATANDO OS CAMPOS DE CODOM DA TABELA SIPPES.REMUNERACAO -- -- ######################################################## -- BEGIN CABECALHO('-- ATUALIZANDO OS CAMPOS DE CODOM DA TABELA SIPPES.REMUNERACAO'); -- ################################# -- -- TRATANDO OS REGISTROS HOMOLOGADOS -- -- ################################# -- MSG_SIMPLES('TRATANDO OS REGISTROS HOMOLOGADOS'); --------------------------------------- -- ATUALIZANDO O CAMPO ORGAO_CODIGO -- --------------------------------------- UPDATE SIPPES.REMUNERACAO T SET T.ORGAO_CODIGO = P_CODOM_NOVO WHERE T.ORGAO_CODIGO = P_CODOM_ATUAL AND EM_TRANSITO_IND = 'N'; IMPRIMIR_MSG(SQL%ROWCOUNT, 'ORGAO_CODIGO');
----------------------------------------------- -- ATUALIZANDO O CAMPO ORGAO_DESTINO_CODIGO -- ----------------------------------------------- UPDATE SIPPES.REMUNERACAO T SET T.ORGAO_DESTINO_CODIGO = P_CODOM_NOVO WHERE T.ORGAO_DESTINO_CODIGO = P_CODOM_ATUAL AND EM_TRANSITO_IND = 'N'; IMPRIMIR_MSG(SQL%ROWCOUNT, 'ORGAO_DESTINO_CODIGO', 'S');
-- ################################# -- -- TRATANDO OS REGISTROS EM TRANSITO -- -- ################################# -- MSG_SIMPLES('TRATANDO OS REGISTROS EM TRANSITO'); --------------------------------------- -- ATUALIZANDO O CAMPO ORGAO_CODIGO -- --------------------------------------- UPDATE SIPPES.REMUNERACAO T SET T.ORGAO_CODIGO = P_CODOM_NOVO WHERE T.ORGAO_CODIGO = P_CODOM_ATUAL AND EM_TRANSITO_IND = 'S'; IMPRIMIR_MSG(SQL%ROWCOUNT, 'ORGAO_CODIGO');
UPDATE SIPPES.REMUNERACAO T SET T.ORGAO_DESTINO_CODIGO = P_CODOM_NOVO WHERE T.ORGAO_DESTINO_CODIGO = P_CODOM_ATUAL AND EM_TRANSITO_IND = 'S'; IMPRIMIR_MSG(SQL%ROWCOUNT, 'ORGAO_DESTINO_CODIGO', 'S');
END MIGRA_OM_REMUN;
PROCEDURE MIGRA_OM_VER_REMUN(P_CODOM_ATUAL IN NUMBER, P_CODOM_NOVO IN NUMBER, P_GESTORA IN NUMBER DEFAULT NULL)IS -- ############################################################### -- -- TRATANDO OS CAMPOS DE CODOM DA TABELA SIPPES.VERSAO_REMUNERACAO -- -- ############################################################### -- BEGIN CABECALHO('-- ATUALIZANDO OS CAMPOS DE CODOM DA TABELA SIPPES.VERSAO_REMUNERACAO'); -- ################################# -- -- TRATANDO OS REGISTROS HOMOLODADOS -- -- ################################# -- MSG_SIMPLES('TRATANDO OS REGISTROS HOMOLOGADOS'); --------------------------------------- -- ATUALIZANDO O CAMPO ORGAO_CODIGO -- --------------------------------------- UPDATE SIPPES.VERSAO_REMUNERACAO T SET T.ORGAO_CODIGO = P_CODOM_NOVO WHERE T.ORGAO_CODIGO = P_CODOM_ATUAL AND T.VERSAO = (SELECT MAX(VW.VERSAO) FROM SIPPES.VERSAO_REM_VIGENTE_VW VW WHERE VW.REM_FAV_PESSOA_IDENT_COD = T.REM_FAV_PESSOA_IDENT_COD AND VW.REM_PREC_CP = T.REM_PREC_CP) AND EM_TRANSITO_IND = 'N'; IMPRIMIR_MSG(SQL%ROWCOUNT, 'ORGAO_CODIGO');
----------------------------------------------- -- ATUALIZANDO O CAMPO ORGAO_DESTINO_CODIGO -- ----------------------------------------------- UPDATE SIPPES.VERSAO_REMUNERACAO T SET T.ORGAO_DESTINO_CODIGO = P_CODOM_NOVO WHERE T.ORGAO_DESTINO_CODIGO = P_CODOM_ATUAL AND T.VERSAO = (SELECT MAX(VW.VERSAO) FROM SIPPES.VERSAO_REM_VIGENTE_VW VW WHERE VW.REM_FAV_PESSOA_IDENT_COD = T.REM_FAV_PESSOA_IDENT_COD AND VW.REM_PREC_CP = T.REM_PREC_CP) AND T.EM_TRANSITO_IND = 'N'; IMPRIMIR_MSG(SQL%ROWCOUNT, 'ORGAO_DESTINO_CODIGO', 'S');
-- ################################# -- -- TRATANDO OS REGISTROS EM TRANSITO -- -- ################################# -- MSG_SIMPLES('TRATANDO OS REGISTROS EM TRANSITO'); --------------------------------------- -- ATUALIZANDO O CAMPO ORGAO_CODIGO -- --------------------------------------- UPDATE SIPPES.VERSAO_REMUNERACAO T SET T.ORGAO_CODIGO = P_CODOM_NOVO WHERE T.ORGAO_CODIGO = P_CODOM_ATUAL AND T.VERSAO = (SELECT MAX(VW.VERSAO) FROM SIPPES.VERSAO_REM_VIGENTE_VW VW WHERE VW.REM_FAV_PESSOA_IDENT_COD = T.REM_FAV_PESSOA_IDENT_COD AND VW.REM_PREC_CP = T.REM_PREC_CP) AND T.EM_TRANSITO_IND = 'S'; IMPRIMIR_MSG(SQL%ROWCOUNT, 'ORGAO_CODIGO');
----------------------------------------------- -- ATUALIZANDO O CAMPO ORGAO_DESTINO_CODIGO -- ----------------------------------------------- UPDATE SIPPES.VERSAO_REMUNERACAO T SET T.ORGAO_DESTINO_CODIGO = P_CODOM_NOVO WHERE T.ORGAO_DESTINO_CODIGO = P_CODOM_ATUAL AND T.VERSAO = (SELECT MAX(VW.VERSAO) FROM SIPPES.VERSAO_REM_VIGENTE_VW VW WHERE VW.REM_FAV_PESSOA_IDENT_COD = T.REM_FAV_PESSOA_IDENT_COD AND VW.REM_PREC_CP = T.REM_PREC_CP) AND T.EM_TRANSITO_IND = 'S'; IMPRIMIR_MSG(SQL%ROWCOUNT, 'ORGAO_DESTINO_CODIGO', 'S');
END MIGRA_OM_VER_REMUN;
PROCEDURE MIGRA_OM_LANCAMENTO(P_CODOM_ATUAL IN NUMBER, P_CODOM_NOVO IN NUMBER, P_GESTORA IN NUMBER DEFAULT NULL)IS -- ######################################################## -- -- TRATANDO OS CAMPOS DE CODOM DA TABELA SIPPES.LANCAMENTO -- -- ######################################################## -- BEGIN CABECALHO('-- ATUALIZANDO OS CAMPOS DE CODOM DA TABELA SIPPES.LANCAMENTO'); ---------------------------------------- -- ATUALIZANDO O CAMPO ORGVAO_CODIGO -- ---------------------------------------- UPDATE SIPPES.LANCAMENTO T SET T.ORGAO_ORIGEM_COD = P_CODOM_NOVO WHERE T.ORGAO_ORIGEM_COD = P_CODOM_ATUAL;
IMPRIMIR_MSG(SQL%ROWCOUNT, 'ORGAO_ORIGEM_COD', 'S');
END MIGRA_OM_LANCAMENTO;
