PROCEDURE MIGRA_OM_OCUPA_PNR(P_CODOM_ATUAL IN NUMBER, P_CODOM_NOVO IN NUMBER, P_GESTORA IN NUMBER DEFAULT NULL)IS -- ######################################################### -- -- TRATANDO OS CAMPOS DE CODOM DA TABELA SIPPES.OCUPACAO_PNR -- -- ######################################################### -- BEGIN CABECALHO('-- ATUALIZANDO OS CAMPOS DE CODOM DA TABELA SIPPES.OCUPACAO_PNR'); ------------------------------------------------------ -- ATUALIZANDO O CAMPO ORGAO_ADMINISTRADORA_CODIGO -- ------------------------------------------------------ UPDATE SIPPES.OCUPACAO_PNR T SET T.ORGAO_ADMINISTRADORA_CODIGO = P_CODOM_NOVO WHERE T.ORGAO_ADMINISTRADORA_CODIGO = P_CODOM_ATUAL;
IMPRIMIR_MSG(SQL%ROWCOUNT, 'ORGAO_ADMINISTRADORA_CODIGO');
------------------------------------------------- -- ATUALIZANDO O CAMPO ORGAO_FUNCIONAL_CODIGO -- ------------------------------------------------- UPDATE SIPPES.OCUPACAO_PNR T SET T.ORGAO_FUNCIONAL_CODIGO = P_CODOM_NOVO WHERE T.ORGAO_FUNCIONAL_CODIGO = P_CODOM_ATUAL;
IMPRIMIR_MSG(SQL%ROWCOUNT, 'ORGAO_FUNCIONAL_CODIGO', 'S');
