IMPRIMIR_MSG(SQL%ROWCOUNT, 'ORGAO_ADMINISTRADORA_CODIGO');
------------------------------------------------- -- ATUALIZANDO O CAMPO ORGAO_FUNCIONAL_CODIGO -- ------------------------------------------------- UPDATE SIPPES.OCUPACAO_PNR_ALT T SET T.ORGAO_FUNCIONAL_CODIGO = P_CODOM_NOVO WHERE T.ORGAO_FUNCIONAL_CODIGO = P_CODOM_ATUAL;
