PROCEDURE MIGRA_OM_USUARIO_REL_PARAM(P_CODOM_ATUAL IN NUMBER, P_CODOM_NOVO IN NUMBER, P_GESTORA IN NUMBER DEFAULT NULL)IS -- ######################################################################## -- -- TRATANDO OS CAMPOS DE CODOM DA TABELA SIPPES.USUARIO_RELATORIO_PARAMETRO -- -- ######################################################################## -- BEGIN CABECALHO('-- ATUALIZANDO OS CAMPOS DE CODOM DA TABELA SIPPES.USUARIO_RELATORIO_PARAMETRO'); --------------------------------------- -- ATUALIZANDO O CAMPO ORGAO_CODIGO -- --------------------------------------- UPDATE SIPPES.USUARIO_RELATORIO_PARAMETRO T SET T.ORGAO_CODIGO = P_CODOM_NOVO WHERE T.ORGAO_CODIGO = P_CODOM_ATUAL;
IMPRIMIR_MSG(SQL%ROWCOUNT, 'ORGAO_CODIGO', 'S');
END MIGRA_OM_USUARIO_REL_PARAM;
PROCEDURE MIGRA_OM_PRFL_USUARIO(P_CODOM_ATUAL IN NUMBER, P_CODOM_NOVO IN NUMBER, P_GESTORA IN NUMBER DEFAULT NULL)IS -- ################################################################# -- -- TRATANDO OS CAMPOS DE CODOM DA TABELA SIPPES.ORGAO_PERFIL_USUARIO -- -- ################################################################# -- BEGIN CABECALHO('-- ATUALIZANDO OS CAMPOS DE CODOM DA TABELA SIPPES.ORGAO_PERFIL_USUARIO'); --------------------------------------- -- ATUALIZANDO O CAMPO ORGAO_CODIGO -- --------------------------------------- UPDATE SIPPES.ORGAO_PERFIL_USUARIO T SET T.ORGAO_CODIGO = P_CODOM_NOVO WHERE T.ORGAO_CODIGO = P_CODOM_ATUAL;
IMPRIMIR_MSG(SQL%ROWCOUNT, 'ORGAO_CODIGO');
END MIGRA_OM_PRFL_USUARIO;
PROCEDURE MIGRA_OM_VERSAO_USUARIO(P_CODOM_ATUAL IN NUMBER, P_CODOM_NOVO IN NUMBER, P_GESTORA IN NUMBER DEFAULT NULL)IS -- ################################################################# -- -- TRATANDO OS CAMPOS DE CODOM DA TABELA SIPPES.VERSAO_USUARIO -- -- ################################################################# -- BEGIN CABECALHO('-- ATUALIZANDO OS CAMPOS DE CODOM DA TABELA SIPPES.VERSAO_USUARIO'); --------------------------------------- -- ATUALIZANDO O CAMPO ORGAO_CODIGO -- --------------------------------------- UPDATE SIPPES.VERSAO_USUARIO VU SET VU.ORGAO_CODIGO = P_CODOM_NOVO WHERE VU.VERSAO = ( SELECT MAX(VU2.VERSAO) FROM SIPPES.VERSAO_USUARIO VU2 WHERE VU2.USUARIO_CODIGO = VU.USUARIO_CODIGO AND VU2.ATIVO_IND = 'S' AND VU2.EXCLUIDO_IND = 'N' AND VU.DATA_EXCLUSAO IS NULL AND TRUNC(SYSDATE) BETWEEN TRUNC(VU.INICIO) AND TRUNC(NVL(VU.FIM, SYSDATE)) ) AND VU.ORGAO_CODIGO = P_CODOM_ATUAL; IMPRIMIR_MSG(SQL%ROWCOUNT, 'ORGAO_CODIGO');
END MIGRA_OM_VERSAO_USUARIO;
PROCEDURE MIGRA_OM_ATUALIZACAO_CADASTRAL(P_CODOM_ATUAL IN NUMBER, P_CODOM_NOVO IN NUMBER, P_GESTORA IN NUMBER DEFAULT NULL)IS -- ################################################################# -- -- TRATANDO OS CAMPOS DE CODOM DA TABELA SIPPES.ATUALIZACAO_CADASTRAL -- -- ################################################################# -- BEGIN CABECALHO('-- ATUALIZANDO OS CAMPOS DE CODOM DA TABELA SIPPES.ATUALIZACAO_CADASTRAL'); --------------------------------------- -- ATUALIZANDO O CAMPO ORGAO_CODIGO -- --------------------------------------- UPDATE SIPPES.ATUALIZACAO_CADASTRAL AC SET AC.ORGAO_CODIGO = P_CODOM_NOVO WHERE AC.TIPO_STATUS_ALT_CODIGO <> 3 AND AC.TIPO_STATUS_ALT_CODIGO <> 4 -- OM DE ORIGEM AND AC.ORGAO_CODIGO = P_CODOM_ATUAL;
IMPRIMIR_MSG(SQL%ROWCOUNT, 'ORGAO_CODIGO');
END MIGRA_OM_ATUALIZACAO_CADASTRAL;
PROCEDURE MIGRA_ORGAO_PAGAMENTO_ALT(P_CODOM_ATUAL IN NUMBER, P_CODOM_NOVO IN NUMBER, P_GESTORA IN NUMBER DEFAULT NULL)IS -- ################################################################# -- -- TRATANDO OS CAMPOS DE CODOM DA TABELA SIPPES.ATUALIZACAO_CADASTRAL -- -- ################################################################# -- BEGIN CABECALHO('-- ATUALIZANDO OS CAMPOS DE CODOM DA TABELA SIPPES.ORGAO_PAGAMENTO_ALT'); ------------------------------------------------- -- ATUALIZANDO O CAMPO UNIDADE_GESTORA_CODIGO -- ------------------------------------------------- UPDATE SIPPES.ORGAO_PAGAMENTO_ALT SET UNIDADE_GESTORA_CODIGO = NULL -- RETIRANDO A VINCUALÇÃO DA UG DO CODOM ANTERIOR WHERE ORGAO_CODIGO = P_CODOM_ATUAL; -- CODOM ANTIGO
IMPRIMIR_MSG(SQL%ROWCOUNT, 'ORGAO_CODIGO');
------------------------------------------------- -- ATUALIZANDO O CAMPO UNID_GESTORA_CODIGO -- -- ATUALIZANDO O CAMPO AUTONOMIA_IND -- ------------------------------------------------- UPDATE SIPPES.ORGAO_PAGAMENTO OP SET UNID_GESTORA_CODIGO = NULL, -- RETIRANDO A VINCUALÇÃO DA UG DO CODOM ANTERIOR AUTONOMIA_IND = 'N' WHERE OP.ORGAO_CODIGO = P_CODOM_ATUAL-- CODOM ANTIGO AND OP.VERSAO = (SELECT MAX (VERSAO) FROM SIPPES.ORGAO_PAGAMENTO OP1 WHERE OP.ORGAO_CODIGO = OP1.ORGAO_CODIGO);
IMPRIMIR_MSG(SQL%ROWCOUNT, 'ORGAO_CODIGO');
------------------------------------------------- -- ATUALIZANDO O CAMPO UNIDADE_GESTORA_CODIGO -- ------------------------------------------------- UPDATE SIPPES.ORGAO_PAGAMENTO_ALT SET UNIDADE_GESTORA_CODIGO = P_GESTORA -- VINCULANDO A UG WHERE ORGAO_CODIGO = P_CODOM_NOVO; -- NOVO CODOM
IMPRIMIR_MSG(SQL%ROWCOUNT, 'ORGAO_CODIGO');
------------------------------------------------- -- ATUALIZANDO O CAMPO UNID_GESTORA_CODIGO -- -- ATUALIZANDO O CAMPO AUTONOMIA_IND -- -- ATUALIZANDO O CAMPO DATA_VINCULACAO -- ------------------------------------------------- UPDATE SIPPES.ORGAO_PAGAMENTO OP SET UNID_GESTORA_CODIGO = P_GESTORA , -- VINCULANDO A UG AUTONOMIA_IND = 'S', -- CONCEDENDO AUTONOMIA DATA_VINCULACAO = SYSDATE WHERE OP.VERSAO = (SELECT MAX (VERSAO) FROM SIPPES.ORGAO_PAGAMENTO OP1 WHERE OP.ORGAO_CODIGO = OP1.ORGAO_CODIGO) AND OP.ORGAO_CODIGO = P_CODOM_NOVO; -- NOVO CODOM
IMPRIMIR_MSG(SQL%ROWCOUNT, 'ORGAO_CODIGO');
END MIGRA_ORGAO_PAGAMENTO_ALT;
PROCEDURE MIGRA_OM(P_CODOM_ATUAL IN NUMBER, P_CODOM_NOVO IN NUMBER, P_GESTORA IN NUMBER DEFAULT NULL)IS -- ################################################################# -- -- REALIZAR A ATUALIZACAO DOS CAMPOS DO CODOM NA TABELAS ENVOLVIDAS -- -- ################################################################# -- BEGIN CABECALHO('-- ATUALIZANDO CODOM DA OM DE:'||P_CODOM_ATUAL||' PARA: '||P_CODOM_NOVO); MSG_SIMPLES('INICIO DA MIGRACAO', 'S'); --------------------------------------- -- ATUALIZANDO AS TABELAS ENVOLVIDAS -- --------------------------------------- MIGRA_OM_FAV_ALT(P_CODOM_ATUAL, P_CODOM_NOVO); MIGRA_OM_REMUN(P_CODOM_ATUAL, P_CODOM_NOVO); MIGRA_OM_VER_REMUN(P_CODOM_ATUAL, P_CODOM_NOVO); MIGRA_OM_LANCAMENTO(P_CODOM_ATUAL, P_CODOM_NOVO); MIGRA_OM_LANCAMENTO_ALT(P_CODOM_ATUAL, P_CODOM_NOVO); MIGRA_OM_LANC_AVLS(P_CODOM_ATUAL, P_CODOM_NOVO); MIGRA_OM_LANC_AVLS_ALT(P_CODOM_ATUAL, P_CODOM_NOVO); MIGRA_OM_OCUPA_PNR(P_CODOM_ATUAL, P_CODOM_NOVO); MIGRA_OM_OCUPA_PNR_ALT(P_CODOM_ATUAL, P_CODOM_NOVO); MIGRA_OM_USUARIO_REL_PARAM(P_CODOM_ATUAL, P_CODOM_NOVO); MIGRA_OM_PRFL_USUARIO(P_CODOM_ATUAL, P_CODOM_NOVO); MIGRA_OM_VERSAO_USUARIO(P_CODOM_ATUAL, P_CODOM_NOVO); MIGRA_OM_ATUALIZACAO_CADASTRAL(P_CODOM_ATUAL, P_CODOM_NOVO); MIGRA_ORGAO_PAGAMENTO_ALT(P_CODOM_ATUAL, P_CODOM_NOVO, P_GESTORA); MSG_SIMPLES('TERMINO DA MIGRACAO', 'S'); END MIGRA_OM;
-- ###################### INICIO DO PROGRAMA ################################### BEGIN -- MIGRA_OM(062117, 062273); -- MIGRA_OM(062125, 062299); -- MIGRA_OM(062133, 062315); -- MIGRA_OM(015677, 015552); -- MIGRA_OM(002030, 002121 ); -- MIGRA_OM(021741, 021782, 160293); MIGRA_OM(013268, 013367);
END; /

            DECLARE

PROCEDURE ATUALIZA_SUBCATEGORIA(P_IDT VARCHAR2, P_SUBCAT NUMBER) IS
V_MSG                   VARCHAR2(255);
V_ERRO					NUMBER := 0;
E_FAVORECIDO_ALT		EXCEPTION;
E_REMUNERACAO			EXCEPTION;
E_VERSAO_REMUNERACAO	EXCEPTION;
/*
----------------------------------------------------
-- VALORES POSSIVEIS PARA SUBCATEGORIA (P_SUBCAT) --
----------------------------------------------------
1	CARREIRA
2	TEMPORARIO
3	EFETIVO VARIAVEL
4	RESERVA
5	REFORMA INCAPACIDADE
6	REFORMA INVALIDEZ
7	ANISTIADO
9	DSA
10	PENSIONISTA
11	REFORMA ORDEM JUDICIAL
12	REFORMA AMPARO ESTADO
13	REFORMA POR IDADE LIMITE
14	INSTITUIDOR DA PENSAO
*/ 
BEGIN


    BEGIN
        UPDATE SIPPES.FAVORECIDO_ALT F
        SET F.SUBCATEGORIA_FAV_CODIGO = P_SUBCAT
        WHERE F.PESSOA_IDENTIFICADOR_COD = P_IDT
        AND   F.VERSAO_ALTERACAO = (SELECT MAX(F2.VERSAO_ALTERACAO) 
                          FROM SIPPES.FAVORECIDO_ALT F2
                          WHERE F2.PESSOA_IDENTIFICADOR_COD = P_IDT)
                          ;

        IF SQL%ROWCOUNT = 0 THEN
			V_ERRO := V_ERRO + 1;
            RAISE E_FAVORECIDO_ALT;
        END IF;

	EXCEPTION
		WHEN E_FAVORECIDO_ALT THEN
			DBMS_OUTPUT.PUT_LINE('ERRO NA ATUALIZACAO DA IDT '|| P_IDT ||' EM SIPPES.FAVORECIDO_ALT');
    END;

    BEGIN
        UPDATE SIPPES.REMUNERACAO R
        SET R.SUBCATEGORIA_FAV_CODIGO = P_SUBCAT
        WHERE R.FAV_PESSOA_IDENT_COD =  P_IDT;

        IF SQL%ROWCOUNT = 0 THEN
			V_ERRO := V_ERRO + 1;
            RAISE E_REMUNERACAO;
        END IF;

	EXCEPTION
		WHEN E_REMUNERACAO THEN
			DBMS_OUTPUT.PUT_LINE('ERRO NA ATUALIZACAO DA IDT '|| P_IDT || ' EM SIPPES.REMUNERACAO');
    END;

    BEGIN
        UPDATE SIPPES.VERSAO_REMUNERACAO R
        SET R.SUBCATEGORIA_FAV_CODIGO = P_SUBCAT
        WHERE R.REM_FAV_PESSOA_IDENT_COD = P_IDT
        AND   R.VERSAO = (SELECT MAX(R2.VERSAO) 
                          FROM SIPPES.VERSAO_REMUNERACAO R2
                          WHERE R2.REM_FAV_PESSOA_IDENT_COD = P_IDT)
                          ;

        IF SQL%ROWCOUNT = 0 THEN
			V_ERRO := V_ERRO + 1;
            RAISE E_VERSAO_REMUNERACAO;
        END IF;

	EXCEPTION
		WHEN E_VERSAO_REMUNERACAO THEN
			DBMS_OUTPUT.PUT_LINE('ERRO NA ATUALIZACAO DA IDT '|| P_IDT || ' EM SIPPES.VERSAO_REMUNERACAO');
    END;

    IF V_ERRO = 0 THEN
       V_MSG := 'ATUALIZACAO DE SUBCATEGORIA  PARA A IDT '|| P_IDT ||' REALIZADA COM SUCESSO';
    END IF;

    DBMS_OUTPUT.PUT_LINE(V_MSG);
END;    
BEGIN   

        ATUALIZA_SUBCATEGORIA('0121661979', 2);
        ATUALIZA_SUBCATEGORIA('0326515673', 2);

END;
/


/*
    SELECT  'FAVORECIDO_ALT', F.SUBCATEGORIA_FAV_CODIGO
    FROM FAVORECIDO_ALT F 
    WHERE F.PESSOA_IDENTIFICADOR_COD IN (
    '0121661979', '0326515673'
    )
    AND F.VERSAO_ALTERACAO = (SELECT MAX(F2.VERSAO_ALTERACAO) 
                              FROM SIPPES.FAVORECIDO_ALT F2
                              WHERE F2.PESSOA_IDENTIFICADOR_COD = F.PESSOA_IDENTIFICADOR_COD)

    --ORDER BY F.VERSAO_ALTERACAO DESC 
    union

    SELECT  'VERSAO_REMUNERACAO', R.SUBCATEGORIA_FAV_CODIGO
    FROM SIPPES.VERSAO_REMUNERACAO R
    WHERE R.REM_FAV_PESSOA_IDENT_COD IN (
    '0121661979', '0326515673'
    )
    AND R.VERSAO = (SELECT MAX(R2.VERSAO) 
                              FROM SIPPES.VERSAO_REMUNERACAO R2
                              WHERE R2.REM_FAV_PESSOA_IDENT_COD = R.REM_FAV_PESSOA_IDENT_COD)
    --ORDER BY R2.VERSAO DESC   
    union

    SELECT 'REMUNERACAO', R3.SUBCATEGORIA_FAV_CODIGO
    FROM SIPPES.REMUNERACAO R3
    WHERE R3.FAV_PESSOA_IDENT_COD IN (
    '0121661979', '0326515673'
    );


