IMPRIMIR_MSG(SQL%ROWCOUNT, 'ORGAO_FUNCIONAL_CODIGO', 'S');
END MIGRA_OM_OCUPA_PNR_ALT;
PROCEDURE MIGRA_OM_USUARIO_REL_PARAM(P_CODOM_ATUAL IN NUMBER, P_CODOM_NOVO IN NUMBER)IS -- ######################################################################## -- -- TRATANDO OS CAMPOS DE CODOM DA TABELA SIPPES.USUARIO_RELATORIO_PARAMETRO -- -- ######################################################################## -- BEGIN CABECALHO('-- ATUALIZANDO OS CAMPOS DE CODOM DA TABELA SIPPES.USUARIO_RELATORIO_PARAMETRO'); --------------------------------------- -- ATUALIZANDO O CAMPO ORGAO_CODIGO -- --------------------------------------- UPDATE SIPPES.USUARIO_RELATORIO_PARAMETRO T SET T.ORGAO_CODIGO = P_CODOM_NOVO WHERE T.ORGAO_CODIGO = P_CODOM_ATUAL;
IMPRIMIR_MSG(SQL%ROWCOUNT, 'ORGAO_CODIGO', 'S');
END MIGRA_OM_USUARIO_REL_PARAM;
PROCEDURE MIGRA_OM_PRFL_USUARIO(P_CODOM_ATUAL IN NUMBER, P_CODOM_NOVO IN NUMBER)IS -- ################################################################# -- -- TRATANDO OS CAMPOS DE CODOM DA TABELA SIPPES.ORGAO_PERFIL_USUARIO -- -- ################################################################# -- BEGIN CABECALHO('-- ATUALIZANDO OS CAMPOS DE CODOM DA TABELA SIPPES.ORGAO_PERFIL_USUARIO'); --------------------------------------- -- ATUALIZANDO O CAMPO ORGAO_CODIGO -- --------------------------------------- UPDATE SIPPES.ORGAO_PERFIL_USUARIO T SET T.ORGAO_CODIGO = P_CODOM_NOVO WHERE T.ORGAO_CODIGO = P_CODOM_ATUAL;
IMPRIMIR_MSG(SQL%ROWCOUNT, 'ORGAO_CODIGO');
END MIGRA_OM_PRFL_USUARIO;
PROCEDURE MIGRA_OM_VERSAO_USUARIO(P_CODOM_ATUAL IN NUMBER, P_CODOM_NOVO IN NUMBER)IS -- ################################################################# -- -- TRATANDO OS CAMPOS DE CODOM DA TABELA SIPPES.VERSAO_USUARIO -- -- ################################################################# -- BEGIN CABECALHO('-- ATUALIZANDO OS CAMPOS DE CODOM DA TABELA SIPPES.VERSAO_USUARIO'); --------------------------------------- -- ATUALIZANDO O CAMPO ORGAO_CODIGO -- --------------------------------------- UPDATE SIPPES.VERSAO_USUARIO VU SET VU.ORGAO_CODIGO = P_CODOM_NOVO WHERE VU.VERSAO = ( SELECT MAX(VU2.VERSAO) FROM SIPPES.VERSAO_USUARIO VU2 WHERE VU2.USUARIO_CODIGO = VU.USUARIO_CODIGO AND VU2.ATIVO_IND = 'S' AND VU2.EXCLUIDO_IND = 'N' AND VU.DATA_EXCLUSAO IS NULL AND TRUNC(SYSDATE) BETWEEN TRUNC(VU.INICIO) AND TRUNC(NVL(VU.FIM, SYSDATE)) ) AND VU.ORGAO_CODIGO = P_CODOM_ATUAL; IMPRIMIR_MSG(SQL%ROWCOUNT, 'ORGAO_CODIGO');
END MIGRA_OM_VERSAO_USUARIO;
PROCEDURE MIGRA_OM_ATUALIZACAO_CADASTRAL(P_CODOM_ATUAL IN NUMBER, P_CODOM_NOVO IN NUMBER)IS -- ################################################################# -- -- TRATANDO OS CAMPOS DE CODOM DA TABELA SIPPES.ATUALIZACAO_CADASTRAL -- -- ################################################################# -- BEGIN CABECALHO('-- ATUALIZANDO OS CAMPOS DE CODOM DA TABELA SIPPES.ATUALIZACAO_CADASTRAL'); --------------------------------------- -- ATUALIZANDO O CAMPO ORGAO_CODIGO -- --------------------------------------- UPDATE SIPPES.ATUALIZACAO_CADASTRAL AC SET AC.ORGAO_CODIGO = P_CODOM_NOVO WHERE AC.TIPO_STATUS_ALT_CODIGO <> 3 AND AC.TIPO_STATUS_ALT_CODIGO <> 4 -- OM DE ORIGEM AND AC.ORGAO_CODIGO = P_CODOM_ATUAL;
IMPRIMIR_MSG(SQL%ROWCOUNT, 'ORGAO_CODIGO');
END MIGRA_OM_ATUALIZACAO_CADASTRAL;
PROCEDURE MIGRA_OM(P_CODOM_ATUAL IN NUMBER, P_CODOM_NOVO IN NUMBER)IS -- ################################################################# -- -- REALIZAR A ATUALIZACAO DOS CAMPOS DO CODOM NA TABELAS ENVOLVIDAS -- -- ################################################################# -- BEGIN CABECALHO('-- ATUALIZANDO CODOM DA OM DE:'||P_CODOM_ATUAL||' PARA: '||P_CODOM_NOVO); MSG_SIMPLES('INICIO DA MIGRACAO', 'S'); --------------------------------------- -- ATUALIZANDO AS TABELAS ENVOLVIDAS -- --------------------------------------- MIGRA_OM_FAV_ALT(P_CODOM_ATUAL, P_CODOM_NOVO); MIGRA_OM_REMUN(P_CODOM_ATUAL, P_CODOM_NOVO); MIGRA_OM_VER_REMUN(P_CODOM_ATUAL, P_CODOM_NOVO); MIGRA_OM_LANCAMENTO(P_CODOM_ATUAL, P_CODOM_NOVO); -- Atualziado 05/06/2025 MIGRA_OM_LANCAMENTO_ALT(P_CODOM_ATUAL, P_CODOM_NOVO); MIGRA_OM_LANC_AVLS(P_CODOM_ATUAL, P_CODOM_NOVO); MIGRA_OM_LANC_AVLS_ALT(P_CODOM_ATUAL, P_CODOM_NOVO); MIGRA_OM_OCUPA_PNR(P_CODOM_ATUAL, P_CODOM_NOVO); MIGRA_OM_OCUPA_PNR_ALT(P_CODOM_ATUAL, P_CODOM_NOVO); MIGRA_OM_USUARIO_REL_PARAM(P_CODOM_ATUAL, P_CODOM_NOVO); MIGRA_OM_PRFL_USUARIO(P_CODOM_ATUAL, P_CODOM_NOVO); MIGRA_OM_VERSAO_USUARIO(P_CODOM_ATUAL, P_CODOM_NOVO); MIGRA_OM_ATUALIZACAO_CADASTRAL(P_CODOM_ATUAL, P_CODOM_NOVO); MSG_SIMPLES('TERMINO DA MIGRACAO', 'S');
END MIGRA_OM;
BEGIN MIGRA_OM(032086,031229);--ATUAL, NOVO END;

﻿-- SOLUCAO REDMINE SIPPES #64417
-- VERIFICANDO O CODIGO DA FOLHA DE PAGAMENTO. SELECT * FROM SIPPES.PROCESSAMENTO_FOLHA_FINALIZA WHERE FOLHA_PGTO_CODIGO = (SELECT CODIGO FROM SIPPES.FOLHA_PAGAMENTO WHERE MES_REFERENCIA = 10 AND ANO_REFERENCIA = 2025) AND NUMERO_PROCESSAMENTO = 2;
-- APAGANDO O REGISTRO NA TABELA SIPPES.PROCESSAMENTO_FOLHA_FINALIZA DELETE FROM SIPPES.PROCESSAMENTO_FOLHA_FINALIZA WHERE FOLHA_PGTO_CODIGO = (SELECT CODIGO FROM SIPPES.FOLHA_PAGAMENTO WHERE MES_REFERENCIA = 10 AND ANO_REFERENCIA = 2025) AND NUMERO_PROCESSAMENTO = 2;
COMMIT;
-- EXECUTAR NOVAMENTE A SIPPES.PROCESSAMENTO_FOLHA_FINALIZA BEGIN SIPPES.PRC_FINALIZA_PROCESSAMENTO(2, 4058, 1); END;
